[ExtensionOf(formControlStr(SalesQuotationListPage, AVAQuotationViaMail))]
final class AVASalesQuotationListPageFrm_AVAQuotationViaMail_Extension
{
}

Method.Source:
/// <summary>
/// clicked method
/// </summary>
public void clicked()
{

    FormControl curButton = any2Object(this) as FormControl;
    FormDataSource          quotationDS = curButton.formRun().dataSource(tableStr(SalesQuotationTable));
    SalesQuotationTable     salesQuotationTable;

    if (quotationDS)
    {
        salesQuotationTable.data(quotationDS.cursor());
    }
    if (salesQuotationTable.Email == '')
    {
        throw Error("@NDX:NXAEmailInQuotMiss");
    }

    next clicked();

    element.avaCreateCustQuotationJour(this);
    element.avaCreateEmail(this);

    if (quotationDS)
    {
        quotationDS.executeQuery();
        quotationDS.positionToRecord(salesQuotationTable);
    }


}
